#include "Halide.h"

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "syrk.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Array initialization, translated from the original C version.
 * Uses simple Halide pipelines for A and C; this is outside the
 * timed region, so we keep the schedule simple.
 */
static
void init_array(int n, int m,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> C,
                Halide::Buffer<num_t, 2> A) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");
    Func init_A("init_A"), init_C("init_C");

    // Original C:
    // for (i = 0; i < n; i++)
    //   for (j = 0; j < m; j++)
    //     A[i][j] = ((i*j+1)%n) / n;
    //
    // C array A[i][j] is mapped to Buffer A(j, i) with shape (m, n).
    init_A(j, i) = cast<num_t>(((i * j + 1) % n)) / cast<int>(n);

    // Original C:
    // for (i = 0; i < n; i++)
    //   for (j = 0; j < n; j++)
    //     C[i][j] = ((i*j+2)%m) / m;
    //
    // C array C[i][j] is mapped to Buffer C(j, i) with shape (n, n).
    init_C(j, i) = cast<num_t>(((i * j + 2) % m)) / cast<int>(m);

    // Simple (default) schedules are fine here – this is initialization
    // and not part of the timed kernel.
    init_A.realize(A);
    init_C.realize(C);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;
    int m = M;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    // C is N x N in C as C[i][j], map to Buffer C(j, i) => shape (n, n)
    // A is N x M in C as A[i][j], map to Buffer A(j, i) => shape (m, n)
    Halide::Buffer<num_t, 2> C(n, n);
    Halide::Buffer<num_t, 2> A(m, n);

    // ImageParams corresponding to C and A
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");

    // Initialize data using Halide
    init_array(n, m, &alpha, &beta, C, A);

    // Bind ImageParams to the concrete Buffers
    C_param.set(C);
    A_param.set(A);

    // Halide Vars and RDom
    Var i("i"), j("j");
    // k iterates over M (first dimension of A, which is stored as A(j, i))
    RDom k(0, A.dim(0).extent(), "k");

    // Build the SYRK kernel in Halide
    // BLAS SYRK:
    //   C := alpha * A * A^T + beta * C
    //
    // Original C kernel (PolyBench):
    // for (i = 0; i < _PB_N; i++) {
    //   for (j = 0; j <= i; j++)
    //     C[i][j] *= beta;
    //   for (k = 0; k < _PB_M; k++) {
    //     for (j = 0; j <= i; j++)
    //       C[i][j] += alpha * A[i][k] * A[j][k];
    //   }
    // }
    //
    // We express this as a single Func over the full N x N domain,
    // leaving the upper triangle unchanged:
    //
    //   C_new[i][j] = C[i][j]                                 if j > i
    //               = beta * C[i][j] +
    //                 alpha * sum_k A[i][k] * A[j][k]         if j <= i
    //
    // Remember mapping to Buffers:
    //   C[i][j]   -> C_param(j, i)
    //   A[i][k]   -> A_param(k, i)
    //   A[j][k]   -> A_param(k, j)

    Func syrk("syrk");

    // Promote the scalar coefficients into Halide Exprs once so they
    // can be reused and (potentially) constant-folded.
    const Expr alpha_expr = Expr(alpha);
    const Expr beta_expr  = Expr(beta);
    const Expr zero_expr  = Expr((num_t)0);

    Expr orig   = C_param(j, i);
    Expr lower  = (j <= i);  // inside lower triangle?

    // Pure definition: apply beta scaling to the lower triangle only,
    // keep the upper triangle as-is.
    Expr scaled = beta_expr * orig;
    syrk(j, i) = select(lower,
                        cast<num_t>(scaled),  // j <= i
                        orig);                // j > i  (unchanged)

    // Reduction over k: accumulate alpha * A[i][k] * A[j][k] for the
    // lower triangle. Upper triangle gets +0 to keep it unchanged.
    Expr prod = alpha_expr * A_param(k, i) * A_param(k, j);
    syrk(j, i) += select(lower,
                         cast<num_t>(prod),
                         cast<num_t>(zero_expr));

    // ----------------------------------------------------------------
    // Scheduling
    // ----------------------------------------------------------------
    //
    // Goals:
    //  - Good cache locality over (i, j, k)
    //  - Exploit parallelism across rows i
    //  - Exploit SIMD across j where possible
    //
    // Storage layout:
    //   C(j, i):  j is x (contiguous), i is y
    //   A(k, i):  k is x (contiguous), i is y
    //
    // The reduction walks k (contiguous in A) and computes each C(i, j)
    // independently, so we parallelize across i and vectorize across j.

    Target target = get_host_target();
    const int vec_width =
        std::max(1, target.natural_vector_size(type_of<num_t>()));

    Var j_outer("j_outer"), j_inner("j_inner");

    // Pure stage: scale by beta and copy upper triangle.
    syrk
        .bound(i, 0, n)
        .bound(j, 0, n)
        // Make j the innermost loop for better spatial locality in C.
        .reorder(j, i)
        // Strip-mine j and vectorize within each strip.
        .split(j, j_outer, j_inner, vec_width)
        .vectorize(j_inner)
        // Rows (i) are independent; parallelize across them.
        .parallel(i);

    // Reduction update: accumulate over k.
    syrk.update()
        // Original logical order: for i, for k, for j. Reorder so that
        // j is innermost to keep C accesses dense, k in the middle, i outer.
        .reorder(j, k, i)
        // Strip-mine j and vectorize the innermost part.
        .split(j, j_outer, j_inner, vec_width)
        .reorder(j_inner, j_outer, k, i)
        .vectorize(j_inner)
        .parallel(i);

    // JIT-compile the kernel once; execution will be timed separately.
    syrk.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result into C (in-place semantics w.r.t the original code).
    // C_param and C share storage, but each element is read once (as 'orig')
    // before being written, so aliasing is safe.
    syrk.realize(C);

    auto end = std::chrono::high_resolution_clock::now();

    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (similar spirit to the original print_array), guarded
    // the same way as in the GEMM example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // C array C[ii][jj] -> Buffer C(jj, ii)
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
