    //   for (j = 0; j < m; j++)
    //     A[i][j] = ((i*j+1)%n) / n;
    //
    // C array A[i][j] is mapped to Buffer A(j, i) with shape (m, n).
    // We keep the same value semantics: integer arithmetic in (i*j+1)%n,
    // then converted to num_t and divided by n as num_t.
    init_A(j, i) = cast<num_t>((i * j + 1) % n) / cast<int>(n);

    // Original C:
    // for (i = 0; i < n; i++)
    //   for (j = 0; j < n; j++)
    //     C[i][j] = ((i*j+2)%m) / m;
    //
    // C array C[i][j] is mapped to Buffer C(j, i) with shape (n, n).
    init_C(j, i) = cast<num_t>((i * j + 2) % m) / cast<int>(m);

    // -------------------------
    // Scheduling for init_A/C
    // -------------------------
    //
    // Both A and C are stored with j as the fastest-varying
    // (x) dimension, so we vectorize across j and parallelize
    // across rows (i). This maximizes throughput while preserving
    // the original initialization semantics.
    Target target = get_host_target();
    const int vec_width = Halide::natural_vector_size<num_t>(target);

    init_A
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    init_C
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    // Realize into the provided Buffers.
    init_A.realize(A);
    init_C.realize(C);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;
    int m = M;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    // C is N x N in C as C[i][j], map to Buffer C(j, i) => shape (n, n)
    // A is N x M in C as A[i][j], map to Buffer A(j, i) => shape (m, n)
    Halide::Buffer<num_t, 2> C(n, n);
    Halide::Buffer<num_t, 2> A(m, n);

    // ImageParams corresponding to C and A
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");

    // Initialize data using Halide
    init_array(n, m, &alpha, &beta, C, A);

    // Halide Vars and RDom
    Var i("i"), j("j");
    // k iterates over the shared inner dimension M (first dimension of A)
    RDom k(0, A.dim(0).extent(), "k");

    // --------------------------------------------------------------------
    // Build the SYRK kernel in Halide
    // --------------------------------------------------------------------
    //
    // BLAS SYRK:
    //   C := alpha * A * A^T + beta * C
    //
    // Original C kernel (PolyBench style):
    //
    // for (i = 0; i < _PB_N; i++) {
    //   for (j = 0; j <= i; j++)
    //     C[i][j] *= beta;
    //   for (k = 0; k < _PB_M; k++) {
    //     for (j = 0; j <= i; j++)
    //       C[i][j] += alpha * A[i][k] * A[j][k];
    //   }
    // }
    //
    // Mapping to our Halide Buffers:
    //   C[i][j]   -> C_param(j, i)
    //   A[i][k]   -> A_param(k, i)
    //   A[j][k]   -> A_param(k, j)
    //
    // We construct a full N x N Func, and use select(j <= i, ..., orig)
    // to restrict updates to the lower triangle:
    //
    //   C_new[i][j] = C[i][j]                                  if j > i
    //                = beta * C[i][j] +
    //                  alpha * sum_k A[i][k] * A[j][k]         if j <= i
    //
    // This exactly matches the original behavior: only the lower
    // triangle is updated; upper triangle is left unchanged.

    Func syrk("syrk");

    Expr alpha_expr = Expr(alpha);
    Expr beta_expr  = Expr(beta);

    // Original C value at (i,j)
    Expr orig = C_param(j, i);

    // Pure definition: scale lower triangle by beta, keep upper triangle unchanged.
    syrk(j, i) = select(j <= i,
                        cast<num_t>(beta_expr) * orig,
                        orig);

    // Reduction over k: add alpha * A[i][k] * A[j][k] for lower triangle.
    syrk(j, i) += select(j <= i,
                         cast<num_t>(alpha_expr) *
                             A_param(k, i) * A_param(k, j),
                         cast<num_t>(0));

    // --------------------------------------------------------------------
    // Scheduling for syrk
    // --------------------------------------------------------------------
    //
    // Storage layout: Buffer is C(x=j, y=i) so j is the contiguous
    // (fastest-varying) dimension. We:
    //   - parallelize over rows (i), which distributes work across cores.
    //   - vectorize across j within each row, to exploit SIMD.
    //   - reorder the update so that j is the innermost loop in the
    //     reduction, to align with vectorization and memory layout.
    //
    // We use the same Target as in initialization to choose a good
    // vector width for the current CPU.
    Target target = get_host_target();
    const int vec_width = Halide::natural_vector_size<num_t>(target);

