    Var i("i"), j("j");
    // k iterates over the inner dimension of A: original BLAS index k in A[i][k]
    RDom k(0, m, "k");

    // Build the SYRK kernel in Halide
    // BLAS SYRK:
    //   C := alpha * A * A^T + beta * C
    //
    // Original C kernel (lower triangle only):
    //
    // for (i = 0; i < _PB_N; i++) {
    //   for (j = 0; j <= i; j++)
    //     C[i][j] *= beta;
    //   for (k = 0; k < _PB_M; k++) {
    //     for (j = 0; j <= i; j++)
    //       C[i][j] += alpha * A[i][k] * A[j][k];
    //   }
