 * Array initialization, translated from the original C version.
 *
 * C layout (C version):  C[i][j] with shape (n, n)
 * Halide layout:         C(j, i) with shape (n, n)
 *
 * A layout (C version):  A[i][j] with shape (n, m)
 * Halide layout:         A(j, i) with shape (m, n)
 */
static void init_array(int n, int m,
                       num_t *alpha,
                       num_t *beta,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> A) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");
    Func init_A("init_A"), init_C("init_C");

    // We keep the original Halide semantics (float division by n/m),
    // but rewrite in a type-correct way that follows Halide's Expr rules.

    // Original C (for A):
    // for (i = 0; i < n; i++)
    //   for (j = 0; j < m; j++)
    //     A[i][j] = ((i*j+1)%n) / n;
    //
    // Mapping to Halide:
    //   C array A[i][j] -> Buffer A(j, i) with shape (m, n)
    Expr n_expr = Expr(n);  // 32-bit int Expr
    Expr a_val  = (i * j + 1) % n_expr;
    // Cast numerator and denominator to num_t so the division is done in that type.
    init_A(j, i) = cast<num_t>(a_val) / cast<num_t>(n_expr);

    // Original C (for C):
    // for (i = 0; i < n; i++)
    //   for (j = 0; j < n; j++)
    //     C[i][j] = ((i*j+2)%m) / m;
    //
    // Mapping to Halide:
    //   C array C[i][j] -> Buffer C(j, i) with shape (n, n)
    Expr m_expr = Expr(m);
    Expr c_val  = (i * j + 2) % m_expr;
    init_C(j, i) = cast<num_t>(c_val) / cast<num_t>(m_expr);

    // Simple but effective schedule for initialization:
    // - Parallelize across rows (i)
    // - Vectorize across the contiguous x-dimension (j)
    Target init_target = get_jit_target_from_environment();
    const int vec_width = init_target.natural_vector_size(type_of<num_t>());

    init_A.compute_root()
          .parallel(i)
          .vectorize(j, vec_width);

    init_C.compute_root()
          .parallel(i)
          .vectorize(j, vec_width);

    // Realize into the provided Buffers.
    init_A.realize(A);
    init_C.realize(C);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;
    int m = M;

    // Host scalars (for readability / compatibility with original code)
    num_t alpha_scalar;
    num_t beta_scalar;

    // Buffers:
    // C is N x N in C as C[i][j], map to Buffer C(j, i) => shape (n, n)
    // A is N x M in C as A[i][j], map to Buffer A(j, i) => shape (m, n)
    Halide::Buffer<num_t, 2> C(n, n);
    Halide::Buffer<num_t, 2> A(m, n);

    // ImageParams corresponding to C and A
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");

    // Scalar parameters for alpha and beta. Using Param<> instead of
    // closing over C++ variables allows us to change them without
    // recompiling the pipeline (though in this benchmark we set them once).
    Param<num_t> alpha_param("alpha");
    Param<num_t> beta_param("beta");

    // Initialize data using Halide
    init_array(n, m, &alpha_scalar, &beta_scalar, C, A);

    // Bind scalar params
    alpha_param.set(alpha_scalar);
    beta_param.set(beta_scalar);

    // Halide Vars and RDom
    Var i("i"), j("j");
    // k iterates over the M dimension (first dimension of A / A_param)
    RDom k(0, m, "k");

    // Build the SYRK kernel in Halide
    // BLAS SYRK:
    //   C := alpha * A * A^T + beta * C
    //
    // Original C kernel (in terms of C[i][j] and A[i][k]):
    //
    // for (i = 0; i < _PB_N; i++) {
    //   for (j = 0; j <= i; j++)
    //     C[i][j] *= beta;
    //   for (k = 0; k < _PB_M; k++) {
    //     for (j = 0; j <= i; j++)
    //       C[i][j] += alpha * A[i][k] * A[j][k];
    //   }
    // }
    //
    // We express this as:
    //   For all i,j:
    //     if (j > i): C_new[i][j] = C[i][j]   (upper triangle unchanged)
    //     if (j <= i): C_new[i][j] = beta*C[i][j] + alpha * sum_k A[i][k]*A[j][k]
    //
    // Mapping from C to Halide:
    //   C[i][j]   -> C_param(j, i)
    //   A[i][k]   -> A_param(k, i)
    //   A[j][k]   -> A_param(k, j)
    //
    // We'll compute a full N x N Func, with a select(j <= i, ..., orig)
    // to restrict updates to the lower triangle.

    Func syrk("syrk");

    Expr orig = C_param(j, i);

    // Pure definition: scale lower triangle by beta, keep upper triangle as-is.
    syrk(j, i) = select(j <= i,
                        beta_param * orig,
                        orig);

    // Reduction over k: add alpha * A[i][k] * A[j][k] for the lower triangle.
    // The upper triangle (j > i) receives a zero increment.
    syrk(j, i) += select(j <= i,
                         alpha_param * A_param(k, i) * A_param(k, j),
                         Expr((num_t)0));

    // Bind ImageParams to the actual Buffers before compiling.
    C_param.set(C);
    A_param.set(A);

    // Target and vector width for optimized schedule
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // ------------------------------------------------------------
    // Scheduling for performance
    // ------------------------------------------------------------
    //
    // Data layout:
    //   - syrk is defined as syrk(j, i)
    //   - In memory, j (x-dimension) is contiguous, i (y-dimension) is strided
    //
    // Strategy:
    //   - Compute syrk at the root (it is the final result).
    //   - Parallelize across rows (i): each row i of C can be computed independently.
    //   - Vectorize across the contiguous j dimension.
    //   - Apply the same strategy to both the pure definition and the
    //     reduction update.
    //
    // We keep the reduction variable k innermost (Halide's default for
    // reductions), which gives a standard "for i, for j, for k" traversal
    // with good locality in A along k and in C along j.

    // Pure definition schedule: row-parallel, vectorized across columns.
    syrk
        .compute_root()
        .reorder(j, i)          // ensure j is the innermost pure dimension
        .parallel(i)            // parallelize over rows of C
        .vectorize(j, vec_width);

    // Update definition schedule: same parallelization pattern.
    // We explicitly reorder so that:
    //   - k is the innermost loop (as required for reductions)
    //   - j is the innermost pure loop, which we vectorize.
    syrk.update()
        .reorder(k, j, i)       // inner-to-outer: k, j, i  => loops: for i, for j, for k
        .parallel(i)
        .vectorize(j, vec_width);

    // Compile the kernel to machine code
    syrk.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result into C (in-place semantics w.r.t the original code)
    syrk.realize(C);

    auto end = std::chrono::high_resolution_clock::now();

    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (similar spirit to the original print_array), guarded
    // the same way as in the GEMM example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // C array C[ii][jj] -> Buffer C(jj, ii)
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
