    Expr beta_expr  = Expr(beta);

    Expr orig = C_param(j, i);

    // Pure definition: scale lower triangle by beta, keep upper triangle
    // unchanged. This corresponds to the first "for (j <= i) C[i][j] *= beta".
    syrk(j, i) = select(j <= i,
